  return tab.evaluate(() => {
    const b = document.querySelector('#board-1 cg-board');
    return b && Math.abs(b.clientWidth - 300) < 2;
  });
}, { timeout: 5000 });
const after = await tab.evaluate(() => {
  const w = document.querySelector('#board-1');
  const b = document.querySelector('#board-1 cg-board');
  return { wrap: [w.clientWidth, w.clientHeight], board: [b.clientWidth, b.clientHeight], pieces: b.querySelectorAll('piece').length };
});
// resize back up to confirm RO fires repeatedly
await tab.evaluate(() => {
  const el = document.querySelector('#board-1');
  el.style.width = '480px';
  el.style.height = '480px';
});
await tab.waitFor(() => {
  return tab.evaluate(() => {
    const b = document.querySelector('#board-1 cg-board');
    return b && Math.abs(b.clientWidth - 480) < 2;
  });
}, { timeout: 5000 });
const up = await tab.evaluate(() => {
  const b = document.querySelector('#board-1 cg-board');
  return { board: [b.clientWidth, b.clientHeight], pieces: b.querySelectorAll('piece').length };
});
return { after, up, errors };

